package com.example.domain.model.i18n

internal object DuaKn1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("ನಿದ್ರೆಯಿಂದ ಎಚ್ಚರಗೊಂಡಾಗ", "ಸಾಯಿಸಿದ ನಂತರ (ನಿದ್ರೆಯ ಮೂಲಕ) ನಮಗೆ ಮತ್ತೆ ಜೀವ ನೀಡಿದ ಅಲ್ಲಾಹನಿಗೆ ಸರ್ವ ಸ್ತುತಿ, ಮತ್ತು ಆತನ ಬಳಿಗೇ ನಾವು ಮರಳಬೇಕು.", "ನಿದ್ರೆಯಿಂದ ಎಚ್ಚರಗೊಂಡ ಕೂಡಲೇ ಅಲ್ಲಾಹನಿಗೆ ಕೃತಜ್ಞತೆ ಸಲ್ಲಿಸಲು.", "ಪ್ರವಾದಿ ﷺ ಎಚ್ಚರಗೊಂಡ ಕೂಡಲೇ ಇದನ್ನು ಪಠಿಸುತ್ತಿದ್ದರು — ಕೃತಜ್ಞತೆ ಮತ್ತು ಪರಲೋಕದ ಸ್ಮರಣೆಯಿಂದ ದಿನ ಆರಂಭ."),
        "dua_leaving_home" to DuaText("ಮನೆಯಿಂದ ಹೊರಡುವಾಗ", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ; ನಾನು ಅಲ್ಲಾಹನಲ್ಲಿ ಭರವಸೆ ಇಟ್ಟಿದ್ದೇನೆ. ಅಲ್ಲಾಹನ ಹೊರತು ಯಾವುದೇ ಶಕ್ತಿ ಅಥವಾ ಬಲ ಇಲ್ಲ.", "ಮನೆಯಿಂದ ಹೊರಡುವಾಗ ಅಲ್ಲಾಹನ ರಕ್ಷಣೆ ಬೇಡಲು.", "ಮಲಕ್‌ಗಳು ಹೇಳುತ್ತಾರೆ: ನಿನಗೆ ಮಾರ್ಗದರ್ಶನ, ಪೋಷಣೆ ಮತ್ತು ರಕ್ಷಣೆ ದೊರೆಯಿತು, ಮತ್ತು ಶೈತಾನ ದೂರ ಸರಿಯುತ್ತಾನೆ."),
        "dua_anxiety_distress" to DuaText("ಚಿಂತೆ ಮತ್ತು ದುಃಖದ ವಿರುದ್ಧ ಪ್ರಾರ್ಥನೆ", "ಓ ಅಲ್ಲಾಹ್, ಚಿಂತೆ ಮತ್ತು ದುಃಖದಿಂದ, ದೌರ್ಬಲ್ಯ ಮತ್ತು ಸೋಮಾರಿತನದಿಂದ, ಜಿಪುಣತನ ಮತ್ತು ಹೇಡಿತನದಿಂದ, ಸಾಲದ ಹೊರೆ ಮತ್ತು ಜನರ ದಬ್ಬಾಳಿಕೆಯಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯ ಬಯಸುತ್ತೇನೆ.", "ದುಃಖ, ಚಿಂತೆ, ಸಾಲದ ಹೊರೆ ಮತ್ತು ಮಾನಸಿಕ ಒತ್ತಡದ ಸಮಯದಲ್ಲಿ.", "ಪ್ರವಾದಿ ﷺ ಇದನ್ನು ಪದೇ ಪದೇ ಪಠಿಸುತ್ತಿದ್ದರು — ದುಃಖ, ಸೋಮಾರಿತನ ಮತ್ತು ಸಾಲದಿಂದ ರಕ್ಷಣೆ."),
        "dua_sayyidul_istighfar" to DuaText("ಸಯ್ಯಿದುಲ್ ಇಸ್ತಿಗ್ಫಾರ್", "ಓ ಅಲ್ಲಾಹ್, ನೀನೇ ನನ್ನ ಪ್ರಭು, ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ. ನೀನು ನನ್ನನ್ನು ಸೃಷ್ಟಿಸಿದೆ, ನಾನು ನಿನ್ನ ದಾಸ. ನನ್ನ ಶಕ್ತಿಗೆ ತಕ್ಕಂತೆ ನಿನ್ನ ಒಪ್ಪಂದ ಮತ್ತು ವಾಗ್ದಾನಕ್ಕೆ ನಾನು ಬದ್ಧನಾಗಿದ್ದೇನೆ. ನನ್ನ ಕೃತ್ಯಗಳ ಕೆಡುಕಿನಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯ ಬಯಸುತ್ತೇನೆ. ನನ್ನ ಮೇಲಿನ ನಿನ್ನ ಅನುಗ್ರಹವನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುತ್ತೇನೆ, ನನ್ನ ಪಾಪವನ್ನೂ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತೇನೆ, ಆದ್ದರಿಂದ ನನ್ನನ್ನು ಕ್ಷಮಿಸು, ಏಕೆಂದರೆ ನಿನ್ನ ಹೊರತು ಯಾರೂ ಪಾಪ ಕ್ಷಮಿಸುವುದಿಲ್ಲ.", "ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಪಠಿಸಲಾಗುತ್ತದೆ — ಪ್ರವಾದಿ ﷺ ಕಲಿಸಿದ ಅತ್ಯುತ್ತಮ ಪಶ್ಚಾತ್ತಾಪ ಪ್ರಾರ್ಥನೆ.", "ದೃಢ ನಂಬಿಕೆಯಿಂದ ಸಂಜೆ ಇದನ್ನು ಪಠಿಸಿ ಅದೇ ರಾತ್ರಿ ಮರಣ ಹೊಂದಿದವನು ಸ್ವರ್ಗ ಪ್ರವೇಶಿಸುತ್ತಾನೆ; ಬೆಳಿಗ್ಗೆ ಪಠಿಸಿದರೂ ಅದೇ ಫಲ."),
        "dua_parents" to DuaText("ಪೋಷಕರಿಗಾಗಿ ಪ್ರಾರ್ಥನೆ", "ನನ್ನ ಪ್ರಭುವೇ, ಅವರು ಬಾಲ್ಯದಲ್ಲಿ ನನ್ನನ್ನು ಪೋಷಿಸಿದಂತೆ ಅವರ ಮೇಲೆ ಕರುಣೆ ತೋರು.", "ಬಾಲ್ಯದ ಪೋಷಣೆಗೆ ಪ್ರತಿಯಾಗಿ ಪೋಷಕರಿಗಾಗಿ ಖುರ್‌ಆನಿಕ ಪ್ರಾರ್ಥನೆ.", "ಅಲ್ಲಾಹನೇ ನಮಗೆ ಪೋಷಕರಿಗಾಗಿ ಈ ಪ್ರಾರ್ಥನೆ ಮಾಡಲು ಆಜ್ಞಾಪಿಸಿದ್ದಾನೆ."),
        "dua_entering_mosque" to DuaText("ಮಸೀದಿ ಪ್ರವೇಶಿಸುವಾಗ", "ಓ ಅಲ್ಲಾಹ್, ನಿನ್ನ ಕರುಣೆಯ ಬಾಗಿಲುಗಳನ್ನು ನನಗೆ ತೆರೆ.", "ಬಲಗಾಲಿನಿಂದ ಮಸೀದಿ ಪ್ರವೇಶಿಸುವಾಗ ಪಠಿಸಲಾಗುತ್ತದೆ.", "ಪ್ರವಾದಿ ﷺ ಮಸೀದಿ ಪ್ರವೇಶಿಸುವಾಗ ಈ ಪ್ರಾರ್ಥನೆ ಕಲಿಸಿದರು."),
        "dua_morning_asbahna" to DuaText("ಬೆಳಗಿನ ಸ್ಮರಣೆ", "ನಾವು ಬೆಳಗನ್ನು ತಲುಪಿದೆವು, ಈ ಬೆಳಗಿನಲ್ಲಿ ಎಲ್ಲಾ ರಾಜ್ಯಾಧಿಕಾರ ಅಲ್ಲಾಹನಿಗೇ ಸೇರಿದೆ. ಎಲ್ಲಾ ಸ್ತುತಿ ಅಲ್ಲಾಹನಿಗೆ. ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ, ಆತ ಏಕಮೇವ, ಆತನಿಗೆ ಪಾಲುದಾರರಿಲ್ಲ. ರಾಜ್ಯಾಧಿಕಾರ ಮತ್ತು ಸ್ತುತಿ ಆತನಿಗೇ, ಆತ ಎಲ್ಲದರ ಮೇಲೆ ಶಕ್ತನಾಗಿದ್ದಾನೆ.", "ಬೆಳಗಿನ ಸಮಯದಲ್ಲಿ ಪಠಿಸುವ ಸುನ್ನತ್ ಪ್ರಾರ್ಥನೆ.", "ಅಲ್ಲಾಹನ ರಾಜ್ಯಾಧಿಕಾರ ಮತ್ತು ಏಕತ್ವದ ಒಪ್ಪಿಗೆಯೊಂದಿಗೆ ದಿನ ಆರಂಭ."),
        "dua_evening_amsayna" to DuaText("ಸಂಜೆಯ ಸ್ಮರಣೆ", "ನಾವು ಸಂಜೆಯನ್ನು ತಲುಪಿದೆವು, ಈ ಸಂಜೆಯಲ್ಲಿ ಎಲ್ಲಾ ರಾಜ್ಯಾಧಿಕಾರ ಅಲ್ಲಾಹನಿಗೇ ಸೇರಿದೆ. ಎಲ್ಲಾ ಸ್ತುತಿ ಅಲ್ಲಾಹನಿಗೆ. ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ, ಆತ ಏಕಮೇವ, ಆತನಿಗೆ ಪಾಲುದಾರರಿಲ್ಲ. ರಾಜ್ಯಾಧಿಕಾರ ಮತ್ತು ಸ್ತುತಿ ಆತನಿಗೇ, ಆತ ಎಲ್ಲದರ ಮೇಲೆ ಶಕ್ತನಾಗಿದ್ದಾನೆ.", "ಸಂಜೆಯ ಸಮಯದಲ್ಲಿ ಪಠಿಸುವ ಸುನ್ನತ್ ಪ್ರಾರ್ಥನೆ.", "ಅಲ್ಲಾಹನ ರಾಜ್ಯಾಧಿಕಾರ ಮತ್ತು ಏಕತ್ವದ ಒಪ್ಪಿಗೆಯೊಂದಿಗೆ ರಾತ್ರಿ ಆರಂಭ."),
        "dua_before_sleep" to DuaText("ನಿದ್ರೆಗೆ ಮೊದಲು", "ಓ ಅಲ್ಲಾಹ್, ನಿನ್ನ ಹೆಸರಿನಲ್ಲಿ ನಾನು ಸಾಯುತ್ತೇನೆ (ನಿದ್ರಿಸುತ್ತೇನೆ) ಮತ್ತು ಬದುಕುತ್ತೇನೆ (ಎಚ್ಚರಗೊಳ್ಳುತ್ತೇನೆ).", "ಹಾಸಿಗೆಯಲ್ಲಿ ಮಲಗಿದ ನಂತರ ಪಠಿಸಲಾಗುತ್ತದೆ.", "ಪ್ರವಾದಿ ﷺ ನಿದ್ರೆಗೆ ಮೊದಲು ಇದನ್ನು ಪಠಿಸುತ್ತಿದ್ದರು."),
        "dua_travel" to DuaText("ಪ್ರಯಾಣದ ಪ್ರಾರ್ಥನೆ", "ಇದನ್ನು ನಮಗೆ ಅಧೀನಗೊಳಿಸಿದವನಿಗೆ ಮಹಿಮೆ ಸಲ್ಲಲಿ, ನಾವು ಸ್ವತಃ ಇದನ್ನು ವಶಪಡಿಸಿಕೊಳ್ಳಲು ಸಾಧ್ಯವಿರಲಿಲ್ಲ, ಮತ್ತು ನಿಶ್ಚಯವಾಗಿ ನಾವು ನಮ್ಮ ಪ್ರಭುವಿನ ಬಳಿಗೆ ಮರಳುವವರು.", "ವಾಹನದಲ್ಲಿ ಕುಳಿತ ನಂತರ ಮೂರು ಬಾರಿ ಅಲ್ಲಾಹು ಅಕ್ಬರ್ ಹೇಳಿದ ಬಳಿಕ ಪಠಿಸಲಾಗುತ್ತದೆ.", "ಸುರಕ್ಷತೆ ಮತ್ತು ಅನುಗ್ರಹಕ್ಕಾಗಿ ಪ್ರಯಾಣದ ಸುನ್ನತ್ ಪ್ರಾರ್ಥನೆ."),
        "dua_ayatul_kursi" to DuaText("ನಮಾಜ್ ನಂತರ ಆಯತುಲ್ ಕುರ್ಸಿ", "ಅಲ್ಲಾಹ್ — ಆತನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ, ಎಂದೆಂದೂ ಜೀವಂತ, ಎಲ್ಲವನ್ನೂ ಪೋಷಿಸುವವನು. ಆತನಿಗೆ ನಿದ್ರೆ ಅಥವಾ ಜೊಂಪು ಬಾಧಿಸುವುದಿಲ್ಲ. ಆಕಾಶಗಳಲ್ಲಿ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿ ಇರುವುದೆಲ್ಲಾ ಆತನಿಗೆ ಸೇರಿದೆ. ಆತನ ಅನುಮತಿ ಇಲ್ಲದೆ ಆತನ ಬಳಿ ಶಿಫಾರಸು ಮಾಡುವವರು ಯಾರು? ಅವರ ಮುಂದೆ ಮತ್ತು ಹಿಂದೆ ಇರುವುದನ್ನು ಆತ ಬಲ್ಲ. ಆತನ ಇಚ್ಛೆ ಇಲ್ಲದೆ ಆತನ ಜ್ಞಾನದಿಂದ ಏನನ್ನೂ ಅವರು ಗ್ರಹಿಸಲಾರರು. ಆತನ ಕುರ್ಸಿ ಆಕಾಶಗಳನ್ನು ಮತ್ತು ಭೂಮಿಯನ್ನು ವ್ಯಾಪಿಸಿದೆ, ಅವುಗಳ ರಕ್ಷಣೆ ಆತನಿಗೆ ಆಯಾಸ ನೀಡುವುದಿಲ್ಲ. ಆತ ಉನ್ನತ, ಮಹಾನ್.", "ಪ್ರತಿ ಕಡ್ಡಾಯ ನಮಾಜಿನ ನಂತರ ಮತ್ತು ನಿದ್ರೆಗೆ ಮೊದಲು ಪಠಿಸಲಾಗುತ್ತದೆ.", "ಪ್ರತಿ ಕಡ್ಡಾಯ ನಮಾಜಿನ ನಂತರ ಇದನ್ನು ಪಠಿಸುವವನಿಗೆ ಸ್ವರ್ಗ ಪ್ರವೇಶಿಸಲು ಮರಣ ಮಾತ್ರ ಅಡ್ಡಿಯಾಗುತ್ತದೆ; ನಿದ್ರೆಗೆ ಮೊದಲು ಪಠಿಸಿದರೆ ಬೆಳಗಿನವರೆಗೆ ರಕ್ಷಣೆ."),
        "dua_hasbunallah" to DuaText("ಅಲ್ಲಾಹ್ ನಮಗೆ ಸಾಕು", "ಅಲ್ಲಾಹ್ ನಮಗೆ ಸಾಕು, ಆತ ಅತ್ಯುತ್ತಮ ರಕ್ಷಕ.", "ಶತ್ರುವಿನ ಭಯ ಅಥವಾ ದೊಡ್ಡ ಅಪಾಯದ ಸಮಯದಲ್ಲಿ.", "ಪ್ರವಾದಿ ಇಬ್ರಾಹೀಮ್ (ಅ.ಸ.) ಬೆಂಕಿಗೆ ಎಸೆಯಲ್ಪಟ್ಟಾಗ ಇದನ್ನು ಹೇಳಿದರು, ಮತ್ತು ಪ್ರವಾದಿ ﷺ ಅಪಾಯದ ಸಮಯದಲ್ಲಿ ಹೇಳಿದರು."),
        "dua_entering_home" to DuaText("ಮನೆ ಪ್ರವೇಶಿಸುವಾಗ", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ (ನಾವು ಪ್ರವೇಶಿಸುತ್ತೇವೆ).", "ಮನೆ ಪ್ರವೇಶಿಸುವಾಗ ಅಲ್ಲಾಹನ ಹೆಸರು ಹೇಳಿ ಸಲಾಮ್ ಮಾಡಲಾಗುತ್ತದೆ.", "ಮನೆ ಪ್ರವೇಶಿಸುವಾಗ ಮತ್ತು ಊಟದ ಸಮಯದಲ್ಲಿ ಅಲ್ಲಾಹನ ಸ್ಮರಣೆ ಮಾಡಿದರೆ ಶೈತಾನ ಹೇಳುತ್ತಾನೆ: ನಿಮಗೆ ಇಲ್ಲಿ ರಾತ್ರಿ ಕಳೆಯಲು ಅಥವಾ ಊಟಕ್ಕೆ ಸ್ಥಳವಿಲ್ಲ."),
        "dua_yunus" to DuaText("ಪ್ರವಾದಿ ಯೂನುಸ್ (ಅ.ಸ.) ಅವರ ಪ್ರಾರ್ಥನೆ", "ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ, ನೀನು ಪರಿಶುದ್ಧ; ನಿಶ್ಚಯವಾಗಿ ನಾನು ಅನ್ಯಾಯ ಮಾಡಿದವರಲ್ಲಿ ಸೇರಿದ್ದೇನೆ.", "ಮೀನಿನ ಹೊಟ್ಟೆಯಲ್ಲಿ ಪ್ರವಾದಿ ಯೂನುಸ್ (ಅ.ಸ.) ಅವರ ಪ್ರಾರ್ಥನೆ — ಪ್ರತಿ ಸಂಕಟಕ್ಕೂ.", "ಯಾವುದೇ ವಿಷಯದಲ್ಲಿ ಈ ಪ್ರಾರ್ಥನೆ ಮಾಡುವ ಮುಸಲ್ಮಾನನಿಗೆ ಅಲ್ಲಾಹ್ ಉತ್ತರ ನೀಡುತ್ತಾನೆ."),
        "dua_karb" to DuaText("ತೀವ್ರ ಸಂಕಟದ ಪ್ರಾರ್ಥನೆ", "ಮಹಾನ್, ಸಹನಶೀಲ ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ. ಮಹಾ ಸಿಂಹಾಸನದ ಪ್ರಭು ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ. ಆಕಾಶಗಳ, ಭೂಮಿಯ ಮತ್ತು ಗೌರವಾನ್ವಿತ ಸಿಂಹಾಸನದ ಪ್ರಭು ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆ ದೇವರಿಲ್ಲ.", "ತೀವ್ರ ಸಂಕಟ ಮತ್ತು ಕಷ್ಟದ ಸಮಯದಲ್ಲಿ ಪಠಿಸಲಾಗುತ್ತದೆ.", "ಪ್ರವಾದಿ ﷺ ಸಂಕಟದ ಸಮಯದಲ್ಲಿ ಇದನ್ನು ಪಠಿಸುತ್ತಿದ್ದರು."),
    )
}
